// embedded_sounds.cpp — looking up the embedded sound files (see
// embedded_sounds.h).
#include "audio/embedded_sounds.h"

#include <cstddef>

// kEmbeddedSounds[]: {path under assets/sounds/, data, size}, ended by a null
// entry. Generated by the makefile.
#include "sounds_wav.h"

namespace audio {

std::span<const unsigned char> EmbeddedSound(std::string_view path) {
    for (const EmbeddedSoundFile* f = kEmbeddedSounds; f->path; ++f)
        if (path == f->path)
            return {f->data, f->size};
    return {};
}

}  // namespace audio
